#!/usr/bin/env bash
# ПРОБЫ С ТРЕМЯ ИСХОДАМИ — общий дом (тред 186; форма принята в #361, тред 185).
#
# ЧТО ЗДЕСЬ ЛЕЧИТСЯ. Сверка «текст содержит» писалась по всем тестовым скриптам одной
# формой:
#
#   "$(printf '%s' "$X" | grep -q 'P' && echo да || echo нет)"
#
# и под `set -uo pipefail` она отвечает `нет` НЕ ТОЛЬКО тогда, когда правило нарушено:
# SIGPIPE писателю, отказ fork под нагрузкой, битый шаблон, отсутствующий файл, любой
# ненулевой код ЛЮБОГО звена — всё это тот же самый `нет`. Два разных исхода —
# «правило нарушено» и «пробы не было вовсе» — становятся неразличимы, а диагностика
# уходит в stderr, которого читатель прогона не видит.
#
# ЗАМЕР, КОТОРЫМ ЭТО СТОИЛО ДЕНЕГ (тред 185): прогон 34377052327 (событие `push`, голова
# caf3fd0cd, шаг `pnpm test`) покрасил `main` РОВНО одной такой сверкой — `назван ЧУЖОЙ
# парк с номером`, `review-delivery.test.sh:165`, — а следующий прогон 34378904884 на
# голове 47ec05764 зелен, при том что диффа в `.github/scripts/**` между этими головами
# нет вовсе. Один и тот же код на одном и том же входе ответил по-разному, и что именно
# не состоялось, из прогона узнать было нечем: ответ `нет` съел вопрос.
#
# ЧЕГО ЭТОТ ФАЙЛ НЕ ОБЕЩАЕТ: он не делает пробы надёжнее и не чинит исходный одноразовый
# отказ (в 185 он не воспроизведён — 3000 прогонов строки и 60 прогонов скрипта под
# нагрузкой, 0 отказов). Предмет — не «чтобы не падало», а «чтобы падение называло себя».
#
# ПОДКЛЮЧЕНИЕ. Файл только определяет функции — ни `set`, ни `cd`, ни временных каталогов
# он не трогает, потому что подключается ВНУТРЬ чужих скриптов со своими трапами:
#
#   source ./probe.sh          # или "${CODE_DIR}/.github/scripts/probe.sh"
#   PROBE_STDERR="$DIR/probe.err"   # свой временный каталог скрипта, см. ниже
#
# ЗАЧЕМ `PROBE_STDERR` И ПОЧЕМУ ОН ОБЯЗАТЕЛЕН. Вторая половина той же болезни: stderr
# пробы сегодня либо шумит в зелёном прогоне, либо гасится `2>/dev/null` и пропадает
# насовсем. Пробы кладут его в ФАЙЛ: зелёный прогон молчит, а `check` вызывающего скрипта
# печатает его при провале — там он и нужен. Умолчания у пути нет намеренно: probe.sh не
# знает, какой каталог скрипт убирает своим трапом, и молча писать в общий `/tmp` значило
# бы оставлять там мусор. Не задан — отказ по имени на первой же пробе.

# ПРОБА ПО СТРОКЕ. Писателя-процесса нет вовсе (here-string вместо конвейера) —
# схлопывать SIGPIPE неоткуда; сам grep читается КОДОМ: 0 → `да`, 1 → `нет`, любой иной →
# третий ответ, который не совпадёт ни с одним ожиданием и назовёт себя по имени.
# Семантика самого grep не трогается — флаги и шаблон едут ему как есть, поэтому ни одна
# сверка не меняет смысла.
#
# ПУСТОЙ СТОГ ИДЁТ В /dev/null, А НЕ ЧЕРЕЗ here-string: `<<<""` — это ОДНА пустая строка, и
# отрицающий шаблон (`-v`) на ней совпал бы, ответив `да` там, где раньше был `нет`.
grep_probe() { # <стог> <аргументы grep…> → да|нет|проба не состоялась (код N)
  local hay="$1" rc=0
  local err="${PROBE_STDERR:?probe.sh: PROBE_STDERR не задан — пробе некуда деть stderr}"
  shift
  if [ -n "$hay" ]; then
    grep -q "$@" <<<"$hay" 2>>"$err" || rc=$?
  else
    grep -q "$@" < /dev/null 2>>"$err" || rc=$?
  fi
  case "$rc" in
    0) echo да ;;
    1) echo нет ;;
    *) echo "проба не состоялась (grep вышел кодом $rc)" ;;
  esac
}

# ТО ЖЕ САМОЕ ДЛЯ ГРЕПА ПО ФАЙЛУ. Конвейера здесь и не было, но два исхода из трёх
# по-прежнему схлопывались: `grep -qF … ./review-delivery.sh && echo да || echo нет`
# отвечает `нет` и когда шаблона в файле нет, и когда ФАЙЛА нет (код 2) — то есть когда
# сверка не состоялась вовсе. Разница дорогая: первое чинят правкой кода, второе — правкой
# самой сверки.
file_probe() { # <аргументы grep…, включая путь> → да|нет|проба не состоялась (код N)
  local rc=0
  local err="${PROBE_STDERR:?probe.sh: PROBE_STDERR не задан — пробе некуда деть stderr}"
  grep -q "$@" 2>>"$err" || rc=$?
  case "$rc" in
    0) echo да ;;
    1) echo нет ;;
    *) echo "проба не состоялась (grep вышел кодом $rc)" ;;
  esac
}

# ПРОБА ПО КОДУ ЧУЖОЙ КОМАНДЫ. Форма `f … >/dev/null 2>&1 && echo да || echo нет` — тот же
# дефект в третьем лице: `нет` там означает «команда отказала», то есть ОЖИДАЕМЫЙ исход, и
# ровно тот же `нет` печатается, когда функции нет в помине (код 127), когда её съел
# `set -e` внутри (код 1) или когда отказал не тот разбор, о котором сверка. Проба,
# которая зеленеет от ОТСУТСТВИЯ проверяемого кода, хуже отсутствующей.
#
# Поэтому ответ — сам код: `код 0` против `код 5` различает «правило нарушено» и «отказ
# именно того разбора», а `код 127` называет несостоявшуюся пробу сам, не совпадая ни с
# одним ожиданием. Stdout команды глушится (сверяется КОД, а не текст), stderr едет в
# `$PROBE_STDERR` — его печатает `check` вызывающего скрипта при провале.
rc_probe() { # <команда…> → «код N»
  local rc=0
  local err="${PROBE_STDERR:?probe.sh: PROBE_STDERR не задан — пробе некуда деть stderr}"
  "$@" > /dev/null 2>>"$err" || rc=$?
  printf 'код %s' "$rc"
}

# ПРОБА ПО ВЫВОДУ ЧУЖОЙ КОМАНДЫ — замена конвейеру `f … | grep -q P && echo да || echo нет`.
# Конвейер здесь схлопывал ТРИ исхода в два дважды: код писателя и код grep. Теперь вывод
# сначала берётся целиком (отказ писателя называется своим кодом и до grep дело не
# доходит), и только потом читается `grep_probe`.
out_probe() { # <команда…> -- <аргументы grep…> → да|нет|проба не состоялась (…)
  local -a cmd=()
  local err="${PROBE_STDERR:?probe.sh: PROBE_STDERR не задан — пробе некуда деть stderr}"
  while [ "$#" -gt 0 ] && [ "$1" != "--" ]; do
    cmd+=("$1")
    shift
  done
  if [ "$#" -eq 0 ]; then
    echo "проба не состоялась (out_probe без разделителя --)"
    return 0
  fi
  shift
  local out rc=0
  out="$("${cmd[@]}" 2>>"$err")" || rc=$?
  if [ "$rc" != 0 ]; then
    echo "проба не состоялась (${cmd[0]} вышла кодом $rc)"
    return 0
  fi
  grep_probe "$out" "$@"
}

# STDERR ПРОБ — ЧИТАТЕЛЮ, А НЕ В /dev/null. Обе функции зовёт `check` вызывающего скрипта,
# и вместе они держат инвариант «накопленный stderr принадлежит ТЕКУЩЕЙ сверке»: прошедшая
# сверка его молча обнуляет, провалившаяся — печатает и обнуляет. Без обнуления на зелёной
# ветви первый же настоящий провал получил бы диагностику от НАМЕРЕННО несостоявшихся проб
# (раздел контроля трёх исходов кормит grep битым шаблоном), то есть чужую.
probe_stderr_report() { # → строки stderr, если он есть; файл обнуляется
  local err="${PROBE_STDERR:-}"
  [ -n "$err" ] && [ -s "$err" ] || return 0
  sed 's/^/       stderr пробы: /' "$err"
  : > "$err"
}

probe_stderr_reset() { # → молча обнулить накопленное
  local err="${PROBE_STDERR:-}"
  [ -n "$err" ] && [ -e "$err" ] && : > "$err"
  return 0
}
